class DistributorHttpTest {
 @Test void actualExperienceHttpBindsCustomerSalesActorsAndPersistsAcknowledgedLifecycle()throws Exception{
  String jdbcUrl=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(jdbcUrl!=null,"distributor HTTP acceptance uses isolated PostgreSQL");var rsaGen=KeyPairGenerator.getInstance("RSA");rsaGen.initialize(2048);var rsa=rsaGen.generateKeyPair();var ecGen=KeyPairGenerator.getInstance("EC");ecGen.initialize(new java.security.spec.ECGenParameterSpec("secp256r1"));var ec=ecGen.generateKeyPair();var jwks=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);String issuer="http://127.0.0.1:"+jwks.getAddress().getPort()+"/realms/offline";jwks.createContext("/",x->{byte[] b=EventCodec.JSON.writeValueAsBytes(Map.of("keys",List.of(new RSAKey.Builder((RSAPublicKey)rsa.getPublic()).keyID("synthetic").algorithm(JWSAlgorithm.RS256).keyUse(KeyUse.SIGNATURE).build().toJSONObject())));x.getResponseHeaders().set("Content-Type","application/json");x.sendResponseHeaders(200,b.length);x.getResponseBody().write(b);x.close();});jwks.start();
  var props=new HashMap<String,Object>();props.put("APP_ENV","test");props.put("NIGSON_SECURITY_ENABLED","true");props.put("NIGSON_PRODUCT_PHASE","3");props.put("NIGSON_EVENTS_ENABLED","false");props.put("NIGSON_JDBC_URL",jdbcUrl+"?currentSchema=experience");props.put("NIGSON_DB_USER","nigson_experience_app");props.put("NIGSON_DB_PASSWORD","mock-experience-runtime");props.put("NIGSON_OIDC_ISSUER",issuer);props.put("NIGSON_OIDC_JWKS",issuer+"/protocol/openid-connect/certs");props.put("NIGSON_PRIVATE_PEER_CIDRS","127.0.0.1/32");props.put("NIGSON_ACTOR_PUBLIC_KEYS",EventCodec.JSON.writeValueAsString(Map.of("active",Base64.getEncoder().encodeToString(ec.getPublic().getEncoded()))));props.put("NIGSON_DISTRIBUTOR_REQUIRED_DOCUMENT_TYPES","CERTIFICATE,IDENTITY");props.put("NIGSON_DISTRIBUTOR_RECIPIENT_GROUP","synthetic-distributor-review");props.put("NIGSON_DISTRIBUTOR_COMMERCE_MODE","mock");byte[] phoneHash=new byte[32],phoneCipher=new byte[32],inboundCipher=new byte[32];Arrays.fill(phoneHash,(byte)7);Arrays.fill(phoneCipher,(byte)8);Arrays.fill(inboundCipher,(byte)9);props.put("NIGSON_MESSAGING_INBOUND_ENABLED","true");props.put("NIGSON_LEAD_RECIPIENT_GROUP","synthetic-sales-triage");props.put("NIGSON_PHONE_CIPHER_REVISION","synthetic");props.put("NIGSON_PHONE_HASH_KEY_VERSION","1");props.put("NIGSON_PHONE_LOCAL_HASH_KEY",Base64.getEncoder().encodeToString(phoneHash));props.put("NIGSON_PHONE_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(phoneCipher));props.put("NIGSON_INBOUND_LOCAL_CIPHER_KEY",Base64.getEncoder().encodeToString(inboundCipher));props.put("NIGSON_INBOUND_RETENTION_DAYS","30");props.put("NIGSON_TWILIO_ACCOUNT_SID","AC0123456789abcdef0123456789abcdef");props.put("NIGSON_TWILIO_AUTH_TOKEN","synthetic-twilio-auth-never-live");props.put("NIGSON_TWILIO_WHATSAPP_FROM","whatsapp:+2348031234567");props.put("NIGSON_TWILIO_WHATSAPP_PUBLIC_URL","https://callbacks.synthetic.invalid/api/v1/webhooks/notifications/twilio/whatsapp");props.put("server.port","0");props.put("logging.level.root","WARN");
  try(var app=new SpringApplicationBuilder(ExperienceApplication.class).properties(props).run();var http=HttpClient.newHttpClient()){
   String base="http://127.0.0.1:"+((WebServerApplicationContext)app).getWebServer().getPort();var jdbc=app.getBean(org.springframework.jdbc.core.JdbcTemplate.class);UUID applicant=UUID.randomUUID(),doc1=file(jdbc,applicant),doc2=file(jdbc,applicant);String path="/api/v1/distributor-applications",body=EventCodec.JSON.writeValueAsString(Map.of("organizationName","Synthetic HTTP distributor","countryCode","NG","businessReference","HTTP-"+UUID.randomUUID(),"documentIds",List.of(doc1,doc2))),key=UUID.randomUUID().toString();UUID corr=UUID.randomUUID();String customer=actorToken(ec,issuer,applicant,"CUSTOMER","distributor.create_WITH_SIGNED_CUSTOMER","POST",path,corr,body);var created=send(http,base+path,"POST",body,workload(rsa,issuer,"nigson-commerce","distributor.create_WITH_SIGNED_CUSTOMER"),customer,corr,key,null);assertThat(created.statusCode()).withFailMessage(created.body()).isEqualTo(201);assertThat(created.headers().firstValue("ETag")).contains("\"0\"");assertThat(send(http,base+path,"POST",body,workload(rsa,issuer,"nigson-commerce","distributor.create_WITH_SIGNED_CUSTOMER"),customer,corr,key,null).body()).isEqualTo(created.body());UUID appId=UUID.fromString(EventCodec.JSON.readTree(created.body()).path("id").asString());
   String minePath="/api/v1/me/distributor-applications";UUID mineCorr=UUID.randomUUID();var mine=send(http,base+minePath,"GET","",workload(rsa,issuer,"nigson-commerce","distributor.read_WITH_SIGNED_CUSTOMER"),actorToken(ec,issuer,applicant,"CUSTOMER","distributor.read_WITH_SIGNED_CUSTOMER","GET",minePath,mineCorr,""),mineCorr,null,null);assertThat(mine.statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(mine.body()).size()).isEqualTo(1);
   String queuePath="/api/v1/staff/distributor-applications?page=0&size=20&sort=submittedAt%2Cdesc";UUID queueCorr=UUID.randomUUID();var queue=send(http,base+queuePath,"GET","",workload(rsa,issuer,"nigson-commerce","distributor.queue_WITH_SIGNED_ACTOR"),actorToken(ec,issuer,UUID.randomUUID(),"SALES","distributor.queue_WITH_SIGNED_ACTOR","GET","/api/v1/staff/distributor-applications",queueCorr,""),queueCorr,null,null);assertThat(queue.statusCode()).withFailMessage(queue.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(queue.body()).path("content").size()).isGreaterThanOrEqualTo(1);
   String detailPath="/api/v1/staff/distributor-applications/"+appId;UUID detailCorr=UUID.randomUUID();var detail=send(http,base+detailPath,"GET","",workload(rsa,issuer,"nigson-commerce","distributor.detail_WITH_SIGNED_ACTOR"),actorToken(ec,issuer,UUID.randomUUID(),"SALES","distributor.detail_WITH_SIGNED_ACTOR","GET",detailPath,detailCorr,""),detailCorr,null,null);assertThat(detail.statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(detail.body()).path("documents").size()).isEqualTo(2);
   String reviewPath=detailPath+"/review",reviewBody="{\"reason\":\"Independent document review complete\",\"documentsVerified\":true}";UUID reviewer=UUID.randomUUID(),reviewCorr=UUID.randomUUID();String reviewKey=UUID.randomUUID().toString();var reviewed=send(http,base+reviewPath,"POST",reviewBody,workload(rsa,issuer,"nigson-commerce","distributor.review_WITH_SIGNED_ACTOR"),actorToken(ec,issuer,reviewer,"SALES","distributor.review_WITH_SIGNED_ACTOR","POST",reviewPath,reviewCorr,reviewBody),reviewCorr,reviewKey,"\"0\"");assertThat(reviewed.statusCode()).withFailMessage(reviewed.body()).isEqualTo(200);assertThat(reviewed.headers().firstValue("ETag")).contains("\"1\"");
   String decisionPath=detailPath+"/decision",decisionBody=EventCodec.JSON.writeValueAsString(Map.of("decision","APPROVE","reason","Approved after independent review","marketId",UUID.randomUUID().toString(),"priceBookId",UUID.randomUUID().toString()));UUID decisionCorr=UUID.randomUUID();String decisionKey=UUID.randomUUID().toString();var approver=UUID.randomUUID();var signed=actorToken(ec,issuer,approver,"SALES","distributor.decision_WITH_SIGNED_ACTOR","POST",decisionPath,decisionCorr,decisionBody);var decided=send(http,base+decisionPath,"POST",decisionBody,workload(rsa,issuer,"nigson-commerce","distributor.decision_WITH_SIGNED_ACTOR"),signed,decisionCorr,decisionKey,"\"1\"");assertThat(decided.statusCode()).withFailMessage(decided.body()).isEqualTo(202);assertThat(EventCodec.JSON.readTree(decided.body()).path("state").asString()).isEqualTo("APPROVED");var replay=send(http,base+decisionPath,"POST",decisionBody,workload(rsa,issuer,"nigson-commerce","distributor.decision_WITH_SIGNED_ACTOR"),signed,decisionCorr,decisionKey,"\"1\"");assertThat(replay.statusCode()).isEqualTo(202);assertThat(replay.body()).isEqualTo(decided.body());
   UUID staleCorr=UUID.randomUUID();var stale=send(http,base+decisionPath,"POST",decisionBody,workload(rsa,issuer,"nigson-commerce","distributor.decision_WITH_SIGNED_ACTOR"),actorToken(ec,issuer,UUID.randomUUID(),"SALES","distributor.decision_WITH_SIGNED_ACTOR","POST",decisionPath,staleCorr,decisionBody),staleCorr,UUID.randomUUID().toString(),"\"0\"");assertThat(stale.statusCode()).isEqualTo(412);
   String suspendBody="{\"decision\":\"SUSPEND\",\"reason\":\"Suspended after compliance review\"}";UUID suspendCorr=UUID.randomUUID();String suspendPath=decisionPath;var suspendSigned=actorToken(ec,issuer,UUID.randomUUID(),"SALES","distributor.decision_WITH_SIGNED_ACTOR","POST",suspendPath,suspendCorr,suspendBody);var suspended=send(http,base+suspendPath,"POST",suspendBody,workload(rsa,issuer,"nigson-commerce","distributor.decision_WITH_SIGNED_ACTOR"),suspendSigned,suspendCorr,UUID.randomUUID().toString(),decided.headers().firstValue("ETag").orElseThrow());assertThat(suspended.statusCode()).withFailMessage(suspended.body()).isEqualTo(202);assertThat(EventCodec.JSON.readTree(suspended.body()).path("state").asString()).isEqualTo("SUSPENDED");assertThat(jdbc.queryForObject("SELECT status FROM experience.distributor_application WHERE id=?",String.class,appId)).isEqualTo("SUSPENDED");
  }finally{jwks.stop(0);}
 }
 private static UUID file(org.springframework.jdbc.core.JdbcTemplate j,UUID owner){UUID id=UUID.randomUUID();j.update("INSERT INTO experience.file_asset(id,created_by,updated_by,owner_party_id,object_key,purpose,mime_type,byte_size,checksum_sha256,classification,scan_status) VALUES (?,'test','test',?,?,'DISTRIBUTOR_PROOF','application/pdf',1000,?,'PRIVATE','CLEAN')",id,owner,"distributor-http/"+id,"b".repeat(64));return id;}
 private static String workload(KeyPair rsa,String issuer,String client,String scope)throws Exception{var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.RS256).keyID("synthetic").build(),new JWTClaimsSet.Builder().issuer(issuer).subject("synthetic-workload").audience("nigson-experience").claim("typ","Bearer").claim("client_id",client).claim("azp",client).claim("scope",scope).issueTime(new Date()).expirationTime(Date.from(Instant.now().plusSeconds(120))).build());jwt.sign(new RSASSASigner((RSAPrivateKey)rsa.getPrivate()));return jwt.serialize();}
 private static String actorToken(KeyPair ec,String issuer,UUID party,String role,String scope,String method,String path,UUID corr,String body)throws Exception{var actor=new ActorAssertion.Actor(party,issuer,"synthetic-user",null,Set.of(role),Set.of(scope),null);var binding=new ActorAssertion.Binding("experience",scope,method,path,corr,ActorAssertion.Binding.bodyHash(body.getBytes(StandardCharsets.UTF_8)));var jwt=new SignedJWT(new JWSHeader.Builder(JWSAlgorithm.ES256).keyID("active").type(new JOSEObjectType("nigson-actor+jwt")).build(),ActorAssertion.claims(actor,binding,Instant.now()));jwt.sign(new ECDSASigner((ECPrivateKey)ec.getPrivate()));return jwt.serialize();}
 private static HttpResponse<String> send(HttpClient http,String url,String method,String body,String bearer,String actor,UUID corr,String key,String etag)throws Exception{var b=HttpRequest.newBuilder(URI.create(url)).timeout(Duration.ofSeconds(10)).header("X-Correlation-ID",corr.toString()).header("Authorization","Bearer "+bearer).header("X-Nigson-Actor",actor);if(key!=null)b.header("Idempotency-Key",key);if(etag!=null)b.header("If-Match",etag);if(!method.equals("GET"))b.header("Content-Type","application/json");return http.send(b.method(method,body.isEmpty()?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}
}
